import{z as A,x as s,o as i,c as d,q as n,j as o,D as e,d as r,s as l,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"混合键合的对准","description":"","frontmatter":{"title":"混合键合的对准","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hybrid-bonding-alignment.md","filePath":"litho/hybrid-bonding-alignment.md","lastUpdated":1791063341000}'),p={name:"litho/hybrid-bonding-alignment.md"};function h(D,a,m,C,b,u){const t=s("Mermaid");return i(),d("div",null,[a[2]||(a[2]=n('<h1 id="混合键合的对准" tabindex="-1">混合键合的对准 <a class="header-anchor" href="#混合键合的对准" aria-label="Permalink to &quot;混合键合的对准&quot;">​</a></h1><div class="epigraph"><p>Cu–Cu 混合键合把两张已图形化的晶圆在三维叠起来；对准误差直接变成 via 错位，量级向着前道套刻靠拢。</p><footer>—— 对照 hybrid bonding overlay（SoIC / Foveros Direct 一类公开叙事）与红外对准</footer></div><p><a href="/litho/packaging-steppers">上一课</a>的微米场对 RDL 够用。缺口是混合键合要求 nm–十 nm 量级的键合对准。本课钉混合键合的对准。光子学波导对侧壁另一套敏感，留给<a href="/litho/photonics-patterning">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>混合键合：介质键合 + 铜垫对铜垫，互连密度远高于凸点。对准：两片晶圆的格子在键合机里对齐，常用红外透过硅看标记，或事先量形变再补偿。误差源：膨胀、键合波、夹持、前道光刻留下的格子（应力课）。这不是投影曝光，但是光刻课程必须收：前道套刻预算与键合预算是一条 3D 链。</p><p><span class="marginnote">术语翻译：混合键合（hybrid bonding）就是两片晶圆先各自做好铜垫与介质面，再面对面直接「贴」在一起——介质对介质粘接、铜垫对铜垫导电，没有焊球这个中间人，所以互连间距能从凸点的几十微米缩到微米以下。</span></p><p>缺口是<strong>键合对准 ≠ 扫描机套刻</strong>，但量级开始同阶。把键手当封装步进器微米问题，会在 CFET/3D 逻辑上翻车。</p><h3 id="与背面电源" tabindex="-1">与背面电源 <a class="header-anchor" href="#与背面电源" aria-label="Permalink to &quot;与背面电源&quot;">​</a></h3><p><a href="/litho/backside-power">背面电源</a> 把另一面引进前道。键合对准是实现手段之一。DTCO 要同时给前道 overlay 与键合 overlay 留预算。</p><p><span class="marginnote">标记必须在键合波长（IR）下可见，且经得起 CMP。关键层对准课的「标记要活过工艺」在此再适用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算：铜垫尺寸 − via 尺寸 − 键合 overlay − 前道 overlay。计量：键合后红外或切片 FA。补偿：预畸变曝光（在扫描机上按预测应变反印）。与 APC：键合机也有自己的匹配与指纹。</p>',12)),(i(),o(B,null,{default:e(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22via%20%E8%83%BD%E4%B8%8D%E8%83%BD%E8%90%BD%E5%9C%A8%E5%AF%B9%E9%9D%A2%E9%93%9C%E5%9E%AB%E9%87%8C%EF%BC%9F%22%5D%20--%3E%20A%5B%22%E9%93%9C%E5%9E%AB%E7%9B%B4%E5%BE%84%22%5D%0A%20%20A%20--%3E%20B%5B%22%E5%87%8F%E5%8E%BB%20via%20%E7%9B%B4%E5%BE%84%20%3D%20%E6%80%BB%E4%BD%99%E9%87%8F%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%88%86%E7%BB%99%E9%94%AE%E5%90%88%E5%AF%B9%E5%87%86%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20B%20--%3E%20D%5B%22%E5%88%86%E7%BB%99%E5%89%8D%E9%81%93%E5%A5%97%E5%88%BB%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20C%20--%3E%20E%7B%22%E4%B8%A4%E9%A1%B9%E9%83%BD%E5%9C%A8%E9%A2%84%E7%AE%97%E5%86%85%EF%BC%9F%22%7D%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%7C%22%E6%98%AF%22%7C%20F%5B%22via%20%E5%85%A8%E8%90%BD%E5%9C%A8%E5%9E%AB%E4%B8%8A%EF%BC%8C%E4%BA%92%E8%BF%9E%E5%AF%BC%E9%80%9A%22%5D%0A%20%20E%20--%3E%7C%22%E5%90%A6%22%7C%20G%5B%22via%20%E5%87%BA%E5%9E%AB%E8%BE%B9%E7%BC%98%20%E2%86%92%20%E5%BC%80%E8%B7%AF%20%2F%20%E9%AB%98%E9%98%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"数字实例：设铜垫 3 µm、via 1 µm，总余量就是约 2 µm，再分给键合对准与前道套刻各一半，单边预算只剩约 1 µm。若下一代把垫缩到亚微米，预算立刻进入 nm 量级——这就是「键合对准向前道套刻看齐」的算术来源。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"键合波从接触点推进，可能引入局部滑移。热循环使 CTE 差变成位移。硅–硅相对均匀，异质键合更差。前道光刻若已把格子写成应力场，键合机无法单独「对准掉」高频项。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：键合波像两片湿玻璃贴合时从按压点扩散的水波——波前扫过之处瞬间「吸」住，若波前带着颗粒或滑移，会把上层格子局部挪动一小段，留下扫描机怎么对准都消不掉的错位指纹。")],-1)),(i(),o(B,null,{default:e(()=>[l(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FE%5B%22%E5%89%8D%E9%81%93%E6%A0%BC%E5%AD%90%20%2F%20%E5%BA%94%E5%8A%9B%22%5D%20--%3E%20HB%5B%22%E9%94%AE%E5%90%88%E5%AF%B9%E5%87%86%22%5D%0A%20%20IR%5B%22%E7%BA%A2%E5%A4%96%E6%A0%87%E8%AE%B0%22%5D%20--%3E%20HB%0A%20%20HB%20--%3E%20VIA%5B%22Cu%20%E5%9E%AB%E5%AF%B9%E4%BD%8D%22%5D%0A%20%20VIA%20--%3E%203D%5B%223D%20%E4%BA%92%E8%BF%9E%E8%89%AF%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不给某厂 nm 键合规格当常数。不把所有 3D 封装当混合键合。本课不讲键合表面化学。</p><p>后课默认：3D 对准有独立预算；下一课回到平面，但对象换成光子波导——关心的是损耗不是晶体管密度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>混合键合对准量级向着前道套刻靠拢，用红外标记与形变补偿。</li><li>前道应力格子进入键合良率，不能只在键合机上修。</li><li>与背面电源、CFET 的 3D 链是同一张预算。</li><li>出处：hybrid bonding overlay 公开叙事。</li></ul>',5))])}const g=A(p,[["render",h]]);export{f as __pageData,g as default};
